// The state of the instance.  This indicates the current state of the
//
//	instance, such as whether it is running, stopped, or in an error state.
type InstanceState string

const (
	InstanceStateStopped  InstanceState = "stopped"
	InstanceStateStarting InstanceState = "starting"
	InstanceStateRunning  InstanceState = "running"
	InstanceStateDraining InstanceState = "draining"
	InstanceStateStopping InstanceState = "stopping"
	InstanceStateStandby  InstanceState = "standby"
)

// AllValues returns all InstanceState values.
func (InstanceState) AllValues() []InstanceState {
	return []InstanceState{
		InstanceStateStopped,
		InstanceStateStarting,
		InstanceStateRunning,
		InstanceStateDraining,
		InstanceStateStopping,
		InstanceStateStandby,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s InstanceState) MarshalText() ([]byte, error) {
	switch s {
	case InstanceStateStopped:
		return []byte(s), nil
	case InstanceStateStarting:
		return []byte(s), nil
	case InstanceStateRunning:
		return []byte(s), nil
	case InstanceStateDraining:
		return []byte(s), nil
	case InstanceStateStopping:
		return []byte(s), nil
	case InstanceStateStandby:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *InstanceState) UnmarshalText(data []byte) error {
	switch InstanceState(data) {
	case InstanceStateStopped:
		*s = InstanceStateStopped
		return nil
	case InstanceStateStarting:
		*s = InstanceStateStarting
		return nil
	case InstanceStateRunning:
		*s = InstanceStateRunning
		return nil
	case InstanceStateDraining:
		*s = InstanceStateDraining
		return nil
	case InstanceStateStopping:
		*s = InstanceStateStopping
		return nil
	case InstanceStateStandby:
		*s = InstanceStateStandby
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

